#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *make_label(int id) {
    char *s = malloc(32);
    if (!s) return NULL;
    snprintf(s, 32, "item-%d", id);
    return s;                          /* caller now owns it */
}

int main(void) {
    for (int i = 0; i < 1000000; i++) {
        char *label = make_label(i);
        puts(label);
        /* missing free(label): 32 bytes lost every iteration */
    }
    return 0;
}

int load(const char *path, char **out_text, size_t *out_len) {
    int rc = -1;
    FILE *fp = NULL;
    char *buf = NULL;

    fp = fopen(path, "rb");
    if (!fp) goto cleanup;
    if (fseek(fp, 0, SEEK_END) != 0) goto cleanup;
    long n = ftell(fp);
    if (n < 0 || fseek(fp, 0, SEEK_SET) != 0) goto cleanup;
    buf = malloc((size_t)n + 1);
    if (!buf) goto cleanup;
    if (fread(buf, 1, (size_t)n, fp) != (size_t)n) goto cleanup;
    buf[n] = '\0';
    *out_text = buf; *out_len = (size_t)n;
    buf = NULL;                 /* ownership moved to the caller */
    rc = 0;
cleanup:
    free(buf);
    if (fp) fclose(fp);
    return rc;
}

int push(int **arr, size_t *len, size_t *cap, int value) {
    if (*len == *cap) {
        size_t ncap = *cap ? *cap * 2 : 8;
        if (ncap > SIZE_MAX / sizeof **arr) return -1;     /* overflow guard */
        int *tmp = realloc(*arr, ncap * sizeof **arr);
        if (!tmp) return -1;           /* *arr is still valid and still owned */
        *arr = tmp; *cap = ncap;
    }
    (*arr)[(*len)++] = value;
    return 0;
}

typedef struct { char *base; size_t used, cap; } Arena;

void *arena_alloc(Arena *a, size_t n) {
    n = (n + 15) & ~(size_t)15;                 /* keep 16-byte alignment */
    if (a->used + n > a->cap) return NULL;
    void *p = a->base + a->used;
    a->used += n;
    return p;
}
void arena_reset(Arena *a) { a->used = 0; }      /* frees everything at once */
void arena_destroy(Arena *a) { free(a->base); a->base = NULL; }

static void close_fp(FILE **fp) { if (*fp) fclose(*fp); }

void demo(const char *path) {
    __attribute__((cleanup(close_fp))) FILE *fp = fopen(path, "r");
    if (!fp) return;
    /* ... any return path closes fp automatically ... */
}

